sys_ux_client_script.script:
/** 
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({api, helpers}) {
    // Get the data from api.data.dynamic_sys_reader_1.output
    const data = api.data.dynamic_sys_reader_1.output;

    // Filter the data to return only items where the value is "saas"
    const filteredData = data.filter(item => item.type === "saas" );

    // Get pagination details from the state
    const currentPage = api.state.currentPage || 1;  // Default to page 1
    const recordsPerPage = 5; // Show 5 records per page

    // Apply pagination
    const startIndex = (currentPage - 1) * recordsPerPage;
    const endIndex = startIndex + recordsPerPage;

    const paginatedData = filteredData.slice(startIndex, endIndex);

    // Return the paginated data
    return paginatedData;
}
